('treadline-express','automotive-services','Treadline Express','The right fit. The right feel. Back on the road.','A tyre, wheel and quick-service centre with tyre discovery, fitment guidance, maintenance checks and booking requests.',ARRAY['Tyre retailers','Wheel and express-service centres']::text[],'{"service_catalog":true,"vehicle_listings":true,"booking_requests":true,"availability_calendar":false,"online_payment":false,"manual_confirmation_required":true,"showcase_preview_only":true,"customer_enquiry_capture":true}'::jsonb,3,true),
